import { enqueueRender } from '../component';
import { assign } from '../util';
import { EMPTY_OBJ } from '../constants';

/**
 * Find the closest error boundary to a thrown error and call it
 * @param {object} error The thrown value
 * @param {VNode} vnode The vnode that threw the error that was caught (except
 * for unmounting when this parameter is the highest parent that was being
 * unmounted)
 * @param {VNode} [oldVNode]
 * @param {ErrorInfo} [errorInfo]
 */
export function _catchError(error, vnode, oldVNode, errorInfo) {
	/** @type {Component} */
	let component;
	/** @type {ComponentType} */
	let ctor;
	/** @type {boolean} */
	let handled;
	let derivedUpdate;
	let pendingState;
	let currentState;
	let clonedState;
	let nextProps;
	let hasDerivedHandler;
	let didCatchHandler;
	let info;
	let shouldEnqueue;
	let sourceState;
	let mergedState;
	let reusePending;
	let updateIsFn;
	let boundaryVNode;
	let derivedFactory;

	for (; (vnode = vnode._parent); ) {
		component = vnode._component;
		if (component != null && !component._processingException) {
			try {
				ctor = component.constructor;
				derivedFactory = null;
				hasDerivedHandler = false;
				derivedUpdate = undefined;
				shouldEnqueue = false;
				pendingState = component._nextState;
				currentState = component.state;
				nextProps = component.props;
				sourceState = currentState != null ? currentState : EMPTY_OBJ;
				clonedState = assign({}, EMPTY_OBJ);
				mergedState = pendingState;
				reusePending = false;
				updateIsFn = false;

				if (ctor != null) {
					derivedFactory = ctor.getDerivedStateFromError;
					hasDerivedHandler = derivedFactory != null;
				}

				if (hasDerivedHandler) {
					derivedUpdate = derivedFactory(error);
					reusePending =
						pendingState != null && pendingState !== currentState;
					mergedState = reusePending
						? pendingState
						: assign({}, sourceState);
					component._nextState = mergedState;
					clonedState = assign(clonedState, mergedState);
					updateIsFn = typeof derivedUpdate == 'function';
					derivedUpdate = updateIsFn
						? derivedUpdate(clonedState, nextProps)
						: derivedUpdate;
					derivedUpdate && assign(mergedState, derivedUpdate);
					boundaryVNode = component._vnode;
					shouldEnqueue = derivedUpdate != null && boundaryVNode != null;
					shouldEnqueue && enqueueRender(component);
