				}

				didCatchHandler = component.componentDidCatch;
				if (didCatchHandler != null) {
					info = errorInfo != null ? errorInfo : {};
					component.componentDidCatch(error, info);
					handled = component._dirty;
				}

				if (handled) {
					component._pendingError = component;
					return component;
				}
			} catch (e) {
				error = e;
			}
