import { createElement, render, Component, Fragment } from 'preact';
import { setupScratch, teardown } from '../../../test/_util/helpers';
import { useErrorBoundary, useState } from 'preact/hooks';
import { setupRerender } from 'preact/test-utils';

/** @jsx createElement */

describe('tmp errorBoundary extra', () => {
	let scratch, rerender;
	beforeEach(() => {
		scratch = setupScratch();
		rerender = setupRerender();
	});
	afterEach(() => {
		teardown(scratch);
	});

	it('cleans up nested subtree and does not duplicate', () => {
		let cwus = 0;
		function Leaf({ throwNow }) {
			if (throwNow) throw new Error('boom');
			return <span>leaf</span>;
		}
		class Inner extends Component {
			componentWillUnmount() { cwus++; }
			render() { return <Leaf throwNow={this.props.throwNow} />; }
		}
		function Boundary() {
			const [err] = useErrorBoundary();
			return err ? <p>fallback</p> : <div><Inner throwNow={false} /></div>;
		}
		function App({ throwNow }) {
			return <section><Boundary /><b>sibling</b><Inner throwNow={throwNow} /></section>;
		}
		render(<App throwNow={false} />, scratch);
		expect(scratch.innerHTML).to.equal('<section><div><span>leaf</span></div><b>sibling</b><span>leaf</span></section>');
		render(<App throwNow={true} />, scratch);
		rerender();
		expect(scratch.innerHTML).to.equal('<section><div><span>leaf</span></div><b>sibling</b><span>leaf</span></section>');
	});

	it('class boundary in list with nested cleanup', () => {
		let cwus = 0;
		function Leaf({ todo }) {
			if (todo.completed) throw new Error('boom');
			return <span>{todo.text}</span>;
		}
		class Inner extends Component {
			componentWillUnmount() { cwus++; }
			render() { return <Leaf todo={this.props.todo} />; }
		}
		class Item extends Component {
			constructor(p) { super(p); this.state = { error: null }; }
			static getDerivedStateFromError(error) { return { error }; }
			render() {
				return this.state.error ? <em>fallback</em> : <Inner todo={this.props.todo} />;
			}
		}
		function App() {
			const [todos, setTodos] = useState([
				{ text: 'a', completed: false },
				{ text: 'b', completed: false }
			]);
			globalThis.__tmpToggle = () => {
				todos[1] = { ...todos[1], completed: true };
				setTodos([...todos]);
			};
			return <ul>{todos.map((t, i) => <Item key={i} todo={t} />)}</ul>;
		}
		render(<App />, scratch);
		expect(scratch.innerHTML).to.equal('<ul><span>a</span><span>b</span></ul>');
		globalThis.__tmpToggle();
		rerender();
		expect(scratch.innerHTML).to.equal('<ul><span>a</span><em>fallback</em></ul>');
		expect(cwus).to.equal(1);
	});

	it('child own update throwing does not duplicate', () => {
		let set;
		function Thrower() {
			const [bad, setBad] = useState(false);
			set = () => setBad(true);
			if (bad) throw new Error('boom');
			return <span>ok</span>;
		}
		function Boundary() {
			const [err] = useErrorBoundary();
			return err ? <p>fallback</p> : <div><Thrower /></div>;
		}
		render(<Boundary />, scratch);
		expect(scratch.innerHTML).to.equal('<div><span>ok</span></div>');
		set();
		rerender();
		expect(scratch.innerHTML).to.equal('<p>fallback</p>');
	});

	it('cDU throw after children changed does not duplicate', () => {
		let throwNow = false;
		class Child extends Component {
			componentDidUpdate() { if (throwNow) throw new Error('boom'); }
			render() { return <span>{this.props.text}</span>; }
		}
		function Boundary() {
			const [err] = useErrorBoundary();
			return err ? <p>fallback</p> : <div><Child text={throwNow ? 'new' : 'old'} /></div>;
		}
		render(<Boundary />, scratch);
		expect(scratch.innerHTML).to.equal('<div><span>old</span></div>');
		throwNow = true;
		render(<Boundary />, scratch);
		rerender();
		expect(scratch.innerHTML).to.equal('<p>fallback</p>');
	});
});
EOF
